begin;
select plan(15);
select has_table('public','artist_availability_rule','availability rule table exists');
select has_table('public','artist_availability_window','availability window table exists');
select ok((select relrowsecurity from pg_class where oid='public.artist_availability_rule'::regclass),'rule RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.artist_availability_window'::regclass),'window RLS enabled');
select ok(not has_table_privilege('authenticated','public.artist_availability_rule','select'),'authenticated has no direct rule read');
select ok(not has_table_privilege('service_role','public.artist_availability_rule','select'),'service role must use guarded RPC');
select ok(has_function_privilege('service_role','public.save_artist_availability_rules(uuid,uuid,uuid,text,integer,integer,integer,jsonb)','execute'),'service role can execute save RPC');
select ok(not has_function_privilege('authenticated','public.save_artist_availability_rules(uuid,uuid,uuid,text,integer,integer,integer,jsonb)','execute'),'authenticated cannot execute save RPC');
set local role service_role;
select lives_ok($$select public.save_artist_availability_rules('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','Europe/Madrid',30,15,15,'[{"weekday":1,"start":"09:00","end":"12:00"}]')$$,'owner saves own artist rules');
select results_eq($$select time_zone,slot_increment_minutes from public.get_artist_availability_configuration('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001')$$,$$values('Europe/Madrid'::text,30)$$,'owner reads rules');
select throws_ok($$select public.save_artist_availability_rules('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','UTC',30,0,0,'[]')$$,'22023',null,'cross-tenant artist rejected');
select throws_ok($$select public.save_artist_availability_rules('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001','UTC',30,0,0,'[]')$$,'42501',null,'artist cannot spoof owner');
select throws_ok($$select public.save_artist_availability_rules('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','UTC',30,0,0,'[{"weekday":1,"start":"09:00","end":"11:00"},{"weekday":1,"start":"10:00","end":"12:00"}]')$$,'22023',null,'overlapping windows rejected atomically');
select results_eq($$select count(*) from public.artist_availability_window where artist_profile_id='50000000-0000-0000-0000-000000000001'$$,$$values(1::bigint)$$,'failed update preserves prior windows');
select throws_ok($$select public.save_artist_availability_rules('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','UTC',30,0,0,'[{"weekday":7,"start":"09:00","end":"10:00"}]')$$,'23514',null,'weekday constraint rejects invalid input');
select * from finish(); rollback;
